#!/usr/bin/env bash
# Generated by scripts/bundle.sh from scripts/install/; edit those, then run scripts/bundle.sh.
# Installs Dispatch on a machine of its own, or updates it:
#
#   curl -fsSL https://raw.githubusercontent.com/chriscorbell/dispatch/main/scripts/install.sh | bash
#
# It checks the machine (Ubuntu or Debian on x86-64, with systemd), asks three things (the bots' time
# zone, how many bots at most, and whether to set up Tailscale too), then downloads the newest release
# from GitHub into /srv/dispatch/releases and runs its scripts/release.sh, the same step
# scripts/deploy.sh runs: it provisions the machine, builds the release and the speech image, and
# starts the dispatch service. A release is a vX.Y.Z tag signed by one of the keys in release_signers
# (scripts/publish.sh makes them), and nothing of it runs until the signature checks out. Dispatch
# serves HTTPS on the local network with a certificate of its own (server/src/https.ts), which
# browsers warn about once per device; Tailscale adds an address with a certificate they trust. The
# answers go to /etc/dispatch/env. Run it again to update to the newest release; the settings stay as
# they are. The app does that itself from Settings > General: it runs the installer of the release it
# is running, unattended (server/src/updates.ts), so each new release is checked against the keys of
# the one before it. /etc/dispatch/source tells it the repository to follow.
#
# At a terminal it takes the whole screen, as an editor does: a screen for each question, with gum's
# lists and buttons (a pinned release from GitHub, checked against its checksum and deleted when the
# installer ends), then the install's steps with their times. When it ends, the terminal gets its
# screen back and the outcome is printed there, so the address to open stays in the scrollback.
# Without gum, on a terminal smaller than 64 by 20, or with nobody at it, it prints its steps line by
# line instead.
#
# Unattended, the answers come from the environment, DISPATCH_TZ, DISPATCH_MAX_BOTS and DISPATCH_TAILSCALE (1 or
# 0), with the defaults for any left out. DISPATCH_YES=1 takes them without asking even at a terminal.
# DISPATCH_REF installs a branch, tag or commit instead of the newest release, with no signature to
# check, and updates then follow that branch. DISPATCH_REPO installs from a fork, and GITHUB_TOKEN
# reads a private one.
#
# Everything is in functions and main runs on the last line, so a download cut short runs nothing.

# ---------------------------------------------------------------- shared by install.sh and uninstall.sh

# Colors and glyphs, plain on a terminal without colors or a locale without UTF-8. Each script keeps
# its own state, set in its main.
ui_init() {
  if [ -t 1 ] && [ "${TERM:-dumb}" != dumb ]; then
    B=$'\e[1m' D=$'\e[2m' R=$'\e[0m' G=$'\e[32m' Y=$'\e[33m' E=$'\e[31m' A=$'\e[38;5;69m' fancy=true
  else
    B='' D='' R='' G='' Y='' E='' A='' fancy=false
  fi
  # shellcheck disable=SC2034 # the uninstaller draws no bars or dots
  case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
    *UTF-8* | *utf8* | *UTF8* | *utf-8*) OK='✓' NO='✗' NOW='●' LATER='○' LINE='─' BAR='│' DOT='·' SPIN=(⠋ ⠙ ⠹ ⠸ ⠼ ⠴ ⠦ ⠧ ⠇ ⠏) ;;
    *) OK='+' NO='x' NOW='*' LATER='o' LINE='-' BAR='|' DOT='-' SPIN=('|' '/' '-' "\\") ;;
  esac
}

info() { printf '   %s\n' "$*"; }
warn() { printf '   %s!%s %s\n' "$Y" "$R" "$*"; }

tui_size() {
  local size
  size="$(stty size </dev/tty 2>/dev/null)" || return 1
  rows=${size% *} cols=${size#* }
}

# The top of every screen, into $head (six rows): Dispatch, what it's doing and where, and the stages.
tui_head() {
  local i plain="  Dispatch  $doing" right=$machine gap stepper='' rule
  gap=$((cols - ${#plain} - ${#right} - 2))
  if [ "$gap" -lt 4 ]; then right='' gap=0; fi
  for i in "${!stages[@]}"; do
    [ "$i" -eq 0 ] || stepper+="  $D$LINE$LINE$R  "
    if [ "$i" -lt "$stage" ]; then stepper+="$G$OK$R ${stages[i]}"
    elif [ "$i" -eq "$stage" ]; then stepper+="$A$NOW$R $B${stages[i]}$R"
    else stepper+="$D$LATER ${stages[i]}$R"; fi
  done
  printf -v rule '%*s' $((cols - 4)) ''
  printf -v head '\e[K\n  %s%sDispatch%s  %s%*s%s%s%s\e[K\n\e[K\n  %s\e[K\n  %s%s%s\e[K\n\e[K\n' \
    "$A" "$B" "$R" "$doing" "$gap" '' "$D" "$right" "$R" "$stepper" "$D" "${rule// /$LINE}" "$R"
}

# become_root <variable>...: both scripts change the whole machine, so they run as root. Run as
# someone else, the script starts again under sudo. Piped from curl, it is gone from stdin by now, so
# it writes itself to a private file from `declare -f` (the same code, not a second download), with
# the named variables from the environment, which stay out of the process list that way, and the
# locale, which decides whether the screen draws with Unicode. sudo gets the terminal as stdin: given
# curl's pipe, Ubuntu's sudo-rs stops the questions' reads from the terminal.
become_root() {
  command -v sudo >/dev/null || die "Run this as root."
  local self v status=0
  self="$(mktemp)"
  {
    for v in "$@" LANG LC_ALL LC_CTYPE; do
      [ -z "${!v:-}" ] || printf 'export %s=%q\n' "$v" "${!v}"
    done
    declare -f
    echo main
  } >"$self"
  if (exec </dev/tty) 2>/dev/null; then
    # shellcheck disable=SC2024 # the redirect is meant to be the caller's
    sudo bash "$self" </dev/tty || status=$?
  else
    sudo bash "$self" || status=$?
  fi
  rm -f "$self"
  exit "$status"
}

# ---------------------------------------------------------------- output

step() { steps=$((steps + 1)); printf '\n%s%s. %s%s\n' "$B" "$steps" "$1" "$R"; }
note() { printf '   %s%s%s\n' "$D" "$*" "$R"; }

# The message goes to the terminal even while a step's output goes to the log (quietly), after the
# full screen has given the terminal back.
die() {
  local fd=2
  if $tty3; then fd=3; fi
  stop_watcher USR1
  tui_end
  printf '\n%s%s%s %s\n' "$E" "$NO" "$R" "$*" >&"$fd"
  reported=true
  exit 1
}

# ask <question> <default> [<preset>]: the preset (from the environment) or, with nobody at a
# terminal, the default, shown as the answer; otherwise what the person types, Enter taking the
# default. The answer goes to stdout, so the prompt goes to the terminal.
ask() {
  local reply="${3:-}"
  if [ -z "$reply" ] && $interactive; then
    printf '   %s %s[%s]%s ' "$1" "$D" "$2" "$R" >/dev/tty
    IFS= read -r reply </dev/tty || true
    reply="$(printf '%s' "$reply" | tr -d '[:space:]')"
    reply="${reply:-$2}"
  else
    reply="${reply:-$2}"
    printf '   %s %s\n' "$1" "$reply" >&2
  fi
  printf '%s' "$reply"
}

# confirm <question>: yes only when the person types y, and always yes unattended.
confirm() {
  $interactive || return 0
  local reply=''
  printf '   %s %s[y/N]%s ' "$1" "$D" "$R" >/dev/tty
  IFS= read -r reply </dev/tty || true
  [[ "$reply" == [yY]* ]]
}

clock() { printf '%d:%02d' $(($1 / 60)) $(($1 % 60)); }

# At full screen, what a step prints goes to the log, and the screen shows the step.
quietly() { if $tui; then "$@" >>"$LOG" 2>&1; else "$@"; fi; }

# mark <key> <words>: one of the installer's own steps. A numbered heading, or at full screen a line
# in the log, where the screen finds it as it finds release.sh's (describe).
mark() { if $tui; then echo "[install] $1" >>"$LOG"; else step "$2"; fi; }

# The full screen or the spinner stops and the terminal is put back, whatever ends the installer.
on_exit() {
  local status=$? fd=2
  if $tty3; then fd=3; fi
  stop_watcher USR1
  tui_end
  if [ "$status" -ne 0 ] && ! $reported; then
    printf '\n%s%s%s Stopped. Run the installer again to pick up where it stopped.%s\n' "$E" "$NO" "$R" "${LOG:+ The log is $LOG.}" >&"$fd"
  fi
  [ -z "$gum_dir" ] || rm -rf "$gum_dir"
  [ -z "$fetch_dir" ] || rm -rf "$fetch_dir"
}

# ---------------------------------------------------------------- the full screen

# gum, for the questions: a pinned release, checked against its checksum, in a temporary folder that
# on_exit removes.
gum_fetch() {
  local version=0.17.0 sum=69ee169bd6387331928864e94d47ed01ef649fbfe875baed1bbf27b5377a6fdb
  local name="gum_${version}_Linux_x86_64"
  gum_dir="$(mktemp -d)"
  curl -fsL --max-time 60 -o "$gum_dir/gum.tar.gz" "https://github.com/charmbracelet/gum/releases/download/v$version/$name.tar.gz" &&
    echo "$sum  $gum_dir/gum.tar.gz" | sha256sum -c --status - &&
    tar -xzf "$gum_dir/gum.tar.gz" -C "$gum_dir" --strip-components=1 "$name/gum" &&
    [ -x "$gum_dir/gum" ]
}

# Full screen when someone is at a terminal big enough and gum downloads; otherwise line by line.
# Drawing goes to fd 3, the terminal, so it stays on screen while steps write to the log.
tui_start() {
  { $interactive && $fancy && tui_size && [ "$rows" -ge 20 ] && [ "$cols" -ge 64 ]; } || return 0
  if ! gum_fetch 2>/dev/null; then
    note "The full-screen installer didn't download, so this one asks line by line."
    return 0
  fi
  GUM="$gum_dir/gum"
  gum_filter=(--indicator '›' --indicator.foreground 69 --match.foreground 69 --prompt '› ' --prompt.foreground 69 --placeholder.foreground 244 --header '' --padding '0 2')
  gum_choose=(--cursor '› ' --cursor.foreground 69 --selected.foreground 69 --header '' --padding '0 2')
  gum_confirm=(--prompt.foreground '' --selected.foreground 255 --selected.background 69 --unselected.foreground 244 --unselected.background '' --padding '0 1')
  exec 3>/dev/tty
  tty3=true tui=true
  printf '\e[?1049h\e[?25l' >&3
  stty -echo </dev/tty 2>/dev/null || true
}

tui_end() {
  $tui || return 0
  tui=false
  printf '\e[?25h\e[?1049l' >&3
  stty echo </dev/tty 2>/dev/null || true
  if [ -s "$gum_dir/steps" ]; then
    { echo; cat "$gum_dir/steps"; } >&3
    rm -f "$gum_dir/steps"
  fi
}

# tui_screen <title> [<line>...]: a fresh screen for a question: its title, then lines about it,
# wrapped to the screen. "" is a blank line, and one starting with ! a warning. Sets avail, the rows
# left below for gum.
tui_screen() {
  local title=$1 line l text='' w n=0 warning first
  shift
  tui_size || true
  tui_head
  w=$((cols - 8))
  [ "$w" -le 76 ] || w=76
  for line in "$@"; do
    if [ -z "$line" ]; then text+=$'\e[K\n' n=$((n + 1)); continue; fi
    warning=false first=true
    if [ "${line:0:1}" = '!' ]; then warning=true line=${line:1}; fi
    while IFS= read -r l; do
      if $warning && $first; then text+="  $Y!$R $l"; elif $warning; then text+="    $l"; else text+="  $l"; fi
      text+=$'\e[K\n' first=false n=$((n + 1))
    done < <(printf '%s\n' "$line" | fold -s -w "$w")
  done
  printf '\e[?25l\e[H\e[2J%s  %s%s%s\e[K\n%s\e[K\n' "$head" "$B" "$title" "$R" "$text" >&3
  avail=$((rows - 6 - 1 - n - 1 - 1))
}

# Someone left at a question (Ctrl+C, or Esc twice): nothing is installed yet.
quit() {
  tui_end
  printf '\nStopped. Nothing was installed.\n' >&3
  reported=true
  exit 130
}

# gum_ask <question> <yes> <no> <default true|false>: 0 for yes, 1 for no; anything else quits.
gum_ask() {
  local status=0
  "$GUM" confirm "$1" --affirmative "$2" --negative "$3" --default="$4" "${gum_confirm[@]}" </dev/tty 2>&3 || status=$?
  [ "$status" -le 1 ] || quit
  return "$status"
}

# One line for each time zone, to pick from: the name with spaces for underscores (so typing "new
# york" finds it), the time there now and its offset from UTC. The given zone comes first.
zone_line() {
  local now off abbr h m sign
  TZ=$1 printf -v now '%(%-I:%M %p)T' -1
  TZ=$1 printf -v off '%(%z)T' -1
  TZ=$1 printf -v abbr '%(%Z)T' -1
  sign=${off:0:1} h=$((10#${off:1:2})) m=${off:3:2}
  if [ "$h$m" = 000 ]; then off=UTC; else off="UTC$sign$h"; [ "$m" = 00 ] || off+=":$m"; fi
  case "$abbr" in "$off" | *[!A-Za-z]*) abbr='' ;; esac
  printf '%-33s %8s   %s\n' "${1//_/ }" "$now" "${abbr:+$abbr $DOT }$off"
}

zone_lines() {
  local z
  zone_line "$1"
  for z in $(timedatectl list-timezones 2>/dev/null); do
    case "$z" in "$1" | Etc/*) ;; *) zone_line "$z" ;; esac
  done
}

pick_tz() {
  local line
  tui_screen "Time zone" "The bots' clocks, routines and check-ins run on it. Type a city or region to find yours."
  line="$(zone_lines "$tz" | "$GUM" filter --height "$avail" --placeholder 'Chicago, Berlin, Tokyo…' "${gum_filter[@]}" 2>&3)" || quit
  line=${line%%  *}
  tz=${line// /_}
}

pick_bots() {
  local most i label current='' pick opts=()
  # About 1 GB each, after 2 GB for voice; at least the four the app defaults to, and at most twelve.
  most=$((ram_gb - 2))
  [ "$most" -le 12 ] || most=12
  [ "$most" -ge 4 ] || most=4
  for ((i = 1; i <= most; i++)); do
    printf -v label '%-9s about %d GB of memory' "$i bot$([ "$i" -eq 1 ] || echo s)" $((i + 2))
    opts+=("$label")
    [ "$i" -ne "$max_bots" ] || current=$label
  done
  tui_screen "How many bots at most" "Each bot has a desktop, Chrome and an agent of its own, and takes about 1 GB of memory. Voice calls take 2 GB more. This machine has $ram_gb GB."
  pick="$("$GUM" choose "${opts[@]}" --selected "$current" --height "$((avail - 1))" "${gum_choose[@]}" </dev/tty 2>&3)" || quit
  max_bots=${pick%% *}
}

pick_tailscale() {
  tui_screen "Tailscale" \
    "Dispatch serves HTTPS with a certificate of its own, which browsers warn about once on each device." "" \
    "Tailscale adds an address with no warning that works from anywhere on your tailnet. It needs a free Tailscale account."
  if gum_ask "Set up Tailscale too?" "Set it up" "Skip" "$([ "$tailscale_too" = 1 ] && echo true || echo false)"; then
    tailscale_too=1
  else
    tailscale_too=0
  fi
}

# The answers on one screen before anything is installed. Change asks every question again.
review() {
  local now
  TZ=$tz printf -v now '%(%-I:%M %p)T' -1
  tui_screen "Ready to install" \
    "${D}Time zone$R   ${tz//_/ } ($now there now)" \
    "${D}Bots$R        up to $max_bots" \
    "${D}Tailscale$R   $([ "$tailscale_too" = 1 ] && echo yes || echo no)" "" \
    "This installs Chrome, Node.js, Docker, Hermes Agent and Dispatch's speech service, and runs Dispatch as a service. It takes 15 to 30 minutes, and can be left to finish."
  gum_ask "Install Dispatch now?" Install Change true
}

# tui_progress <offset> <note> <key>...: the install screen, from the log after <offset>, until TERM
# (it finished) or USR1 (it stopped). The keys are the steps expected, shown ahead and dimmed; other
# steps are added where they come, and expected ones that never come are dropped.
tui_progress() {
  local offset=$1 note=$2
  shift 2
  local keys=("$@") words=() states=() began=() took=() k d cur=-1 tick=0 shown=0 begun=$SECONDS size='' url='' marks=() tail=()
  for k in "${keys[@]}"; do
    d="$(describe "$k")"
    words+=("${d#*|}") states+=(later) began+=(0) took+=(0)
  done
  trap 'end_steps "done"; stage=${#stages[@]}; draw_progress; record_steps; exit 0' TERM
  trap 'end_steps failed; draw_progress; record_steps; exit 0' USR1
  while :; do
    [ $((tick % 6)) -ne 0 ] || read_progress
    draw_progress
    tick=$((tick + 1))
    sleep 0.15
  done
}

# The steps so far, the newest lines after the last one (a ring of 40 in awk), and a link Tailscale
# is waiting on. Called inside tui_progress, whose locals it fills.
read_progress() {
  local got=() line d
  mapfile -t got < <(tail -c "+$((offset + 1))" "$LOG" 2>/dev/null | awk -v n=40 '
    /^\[(install|provision|release)\] / { print "M" substr($0, index($0, "] ") + 2); c = 0; url = ""; next }
    {
      gsub(/\033\[[0-9;?]*[ -\/]*[@-~]/, ""); sub(/.*\r/, ""); gsub(/[[:cntrl:]]/, ""); sub(/^ +/, "")
      if (match($0, /https:\/\/login\.tailscale\.com\/[^ ]+/)) url = substr($0, RSTART, RLENGTH)
      if ($0 != "") buf[c++ % n] = $0
    }
    END { if (url != "") print "U" url; for (i = (c > n ? c - n : 0); i < c; i++) print "L" buf[i % n] }')
  marks=() tail=() url=''
  for line in "${got[@]}"; do
    case "$line" in M*) marks+=("${line:1}") ;; U*) url=${line:1} ;; L*) tail+=("${line:1}") ;; esac
  done
  while [ "$shown" -lt "${#marks[@]}" ]; do
    d="$(describe "${marks[shown]}")"
    shown=$((shown + 1))
    [ -z "$d" ] || begin_step "${d%%|*}" "${d#*|}"
  done
}

# begin_step <key> <words>: the current step is done, and this one runs: the next expected one with
# its key (any expected before it never came), or a new one after the current.
begin_step() {
  local key=$1 j=-1 i
  if [ "$cur" -ge 0 ]; then states[cur]='done' took[cur]=$((SECONDS - began[cur])); fi
  for ((i = cur + 1; i < ${#keys[@]}; i++)); do
    if [ "${keys[i]}" = "$key" ]; then j=$i; break; fi
  done
  if [ "$j" -ge 0 ]; then
    for ((i = cur + 1; i < j; i++)); do states[i]=skipped; done
  else
    j=$((cur + 1))
    keys=("${keys[@]:0:j}" "$key" "${keys[@]:j}") words=("${words[@]:0:j}" '' "${words[@]:j}")
    states=("${states[@]:0:j}" '' "${states[@]:j}") began=("${began[@]:0:j}" 0 "${began[@]:j}") took=("${took[@]:0:j}" 0 "${took[@]:j}")
  fi
  words[j]=$2 states[j]=running began[j]=$SECONDS cur=$j
}

# end_steps done|failed: the current step ends so; at done, expected steps that never came go.
end_steps() {
  local i
  if [ "$cur" -ge 0 ]; then states[cur]=$1 took[cur]=$((SECONDS - began[cur])); fi
  if [ "$1" = "done" ]; then
    for i in "${!states[@]}"; do [ "${states[i]}" != later ] || states[i]=skipped; done
  fi
}

# The steps as lines for the terminal's own screen, which tui_end prints there, so they outlast the
# full screen.
record_steps() {
  local i t icon
  for i in "${!keys[@]}"; do
    case "${states[i]}" in "done") icon="$G$OK$R" ;; failed) icon="$E$NO$R" ;; *) continue ;; esac
    t=${took[i]}
    printf '   %s %s %s%d:%02d%s\n' "$icon" "${words[i]}" "$D" $((t / 60)) $((t % 60)) "$R"
  done >"$gum_dir/steps"
}

draw_progress() {
  local s out i icon text time t w pad room n=0 total
  s="$(stty size </dev/tty 2>/dev/null)" || s="$rows $cols"
  rows=${s% *} cols=${s#* }
  out=$'\e[?25l\e[H'
  if [ "$s" != "$size" ]; then out+=$'\e[2J'; size=$s; fi
  tui_head
  out+=$head
  w=$((cols - 4))
  [ "$w" -le 80 ] || w=80
  if [ -n "$note" ] && [ "$stage" -lt "${#stages[@]}" ]; then out+="  $D${note:0:w}$R"$'\e[K\n\e[K\n' n=2; fi
  for i in "${!keys[@]}"; do
    case "${states[i]}" in
      done) icon="$G$OK$R" t=${took[i]} ;;
      failed) icon="$E$NO$R" t=${took[i]} ;;
      running) icon="$A${SPIN[tick % ${#SPIN[@]}]}$R" t=$((SECONDS - began[i])) ;;
      later) icon=' ' t=-1 ;;
      *) continue ;;
    esac
    time=''
    [ "$t" -lt 0 ] || printf -v time '%d:%02d' $((t / 60)) $((t % 60))
    text=${words[i]}
    [ "${#text}" -le $((w - 12)) ] || text="${text:0:w-13}…"
    pad=$((w - 4 - ${#text} - ${#time}))
    case "${states[i]}" in later) text="$D$text$R" ;; running) text="$B$text$R" ;; esac
    printf -v text '  %s %s%*s%s%s%s' "$icon" "$text" "$pad" '' "$D" "$time" "$R"
    out+="$text"$'\e[K\n'
    n=$((n + 1))
  done
  out+=$'\e[K\n'
  # What the running step is doing: the link Tailscale waits on, or the newest lines of the log.
  room=$((rows - 6 - n - 1 - 3))
  if [ "$cur" -ge 0 ] && [ "${states[cur]}" = running ]; then
    if [ "${keys[cur]}" = tailscale ] && [ -n "$url" ]; then
      out+="    Tailscale is waiting for you. Open this link:"$'\e[K\n'"    $A$url$R"$'\e[K\n'
    elif [ "$room" -gt 0 ]; then
      for ((i = ${#tail[@]} > room ? ${#tail[@]} - room : 0; i < ${#tail[@]}; i++)); do
        out+="    $D$BAR ${tail[i]:0:w-6}$R"$'\e[K\n'
      done
    fi
  fi
  out+=$'\e[J'
  # The foot: how long it has taken, and where the whole log is.
  total=$((SECONDS - begun))
  printf -v time '%d:%02d' $((total / 60)) $((total % 60))
  if [ "$stage" -ge "${#stages[@]}" ]; then time="Done in $time"; else time="$time so far"; fi
  pad=$((cols - 4 - ${#time} - ${#LOG} - 5))
  [ "$pad" -ge 2 ] || pad=2
  printf -v s '\e[%d;1H  %s%s%*sLog: %s%s\e[K' "$rows" "$D" "$time" "$pad" '' "$LOG" "$R"
  printf '%s%s' "$out" "$s" >&3
}

# The install screen starts with the steps a fresh install or an update has ahead of it.
work_begin() {
  $tui || return 0
  local keys=() note offset
  stage=$((${#stages[@]} - 2))
  if [ "${tailscale_too:-0}" = 1 ]; then keys+=(tailscale); fi
  # A release comes built; a branch (DISPATCH_REF) is built here.
  local build=()
  [ -z "$ref" ] || build=(build)
  if $installed; then
    keys+=(download "${build[@]}" start)
    note="Dispatch keeps running until the new version is ready."
  else
    keys+=(download provision packages hermes "${build[@]}" speech start)
    note="This takes 10 to 30 minutes, and can be left to finish."
  fi
  # Measured here, not in the background job, which could start after the first step is written.
  offset="$(stat -c %s "$LOG")"
  tui_progress "$offset" "$note" "${keys[@]}" &
  watcher=$!
}

# Every step done: a moment on the finished screen, then the terminal's own again.
work_end() {
  $tui || return 0
  stop_watcher TERM
  sleep 1
  tui_end
}

# stop_watcher TERM|USR1: the progress display, finished or failed.
stop_watcher() {
  [ -n "${watcher:-}" ] || return 0
  kill "-$1" "$watcher" 2>/dev/null || true
  wait "$watcher" 2>/dev/null || true
  watcher=''
}

# ---------------------------------------------------------------- the machine

check_machine() {
  local id='' like='' version='' name='' problems=() p
  # The releases the installer has been run on end to end: a bot's screen, Chrome, agent and voice.
  # Ubuntu 26.04 is the main one. provision.sh needs apt and the Ubuntu or Debian repositories of
  # Chrome, Node.js and Docker, so their derivatives may work too, with a warning. (Inside the
  # function: become_root carries functions only.)
  local tested='ubuntu 26.04|ubuntu 24.04|ubuntu 22.04|debian 13|debian 12'
  [ "$(uname -s)" = Linux ] || die "Dispatch installs on Ubuntu or Debian."
  [ "$(uname -m)" = x86_64 ] || die "Dispatch needs an x86-64 (amd64) machine; this one is $(uname -m)."
  # shellcheck disable=SC1091
  [ -r /etc/os-release ] && { id="$(. /etc/os-release && echo "${ID:-}")"; like="$(. /etc/os-release && echo "${ID_LIKE:-}")"; version="$(. /etc/os-release && echo "${VERSION_ID:-}")"; name="$(. /etc/os-release && echo "${PRETTY_NAME:-}")"; }
  case " $id $like " in *" ubuntu "* | *" debian "*) ;; *) die "Dispatch installs on Ubuntu or Debian, and this is ${name:-another system}." ;; esac
  [ -d /run/systemd/system ] || die "Dispatch runs as a systemd service, and systemd isn't running here. Install it on a machine or VM of its own, not in a container."
  local tool
  for tool in curl tar gzip; do
    command -v "$tool" >/dev/null || die "This needs $tool: apt-get install $tool"
  done

  ram_gb="$(awk '/^MemTotal:/ { printf "%d", $2 / 1048576 + 0.5 }' /proc/meminfo)"
  local disk_gb cpus
  disk_gb="$(df -BG --output=avail / | awk 'NR == 2 { print $1 + 0 }')"
  cpus="$(nproc)"
  machine="$name $DOT $cpus CPUs $DOT $ram_gb GB"
  $tui || info "$name, $cpus CPUs, $ram_gb GB of memory, $disk_gb GB free"

  case "|$tested|" in *"|$id $version|"*) ;; *) problems+=("Dispatch is made for Ubuntu 26.04 and tested on Ubuntu 22.04 and 24.04 and Debian 12 and 13. ${name:-This system} may work, but isn't tested.") ;; esac
  [ "$ram_gb" -ge 4 ] || problems+=("Dispatch wants about 2 GB of memory for voice and 1 GB per bot, and this machine has $ram_gb GB.")
  [ "$disk_gb" -ge 25 ] || problems+=("Dispatch needs about 25 GB of disk for Chrome, Hermes Agent and the speech service, and $disk_gb GB is free.")
  if ! $installed && ss -Hltn "sport = :$PORT" 2>/dev/null | grep -q .; then
    die "Something else is using port $PORT, which Dispatch needs: $(ss -Hltnp "sport = :$PORT" | grep -o 'users:.*' | head -1)"
  fi
  [ ${#problems[@]} -gt 0 ] || return 0
  if $tui; then
    local lines=()
    for p in "${problems[@]}"; do lines+=("!$p"); done
    tui_screen "This machine" "$name, $cpus CPUs, $ram_gb GB of memory and $disk_gb GB free." "" "${lines[@]}"
    gum_ask "Continue anyway?" Continue Quit false || quit
  else
    for p in "${problems[@]}"; do warn "$p"; done
    confirm "Continue anyway?" || die "Stopped."
  fi
}

valid_tz() {
  [[ "$1" =~ ^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+)*$ ]] || return 1
  [ ! -d /usr/share/zoneinfo ] || [ -f "/usr/share/zoneinfo/$1" ]
}

ask_settings() {
  local tz_default suggested
  tz_default="$(timedatectl show -p Timezone --value 2>/dev/null || true)"
  case "$tz_default" in '' | Etc/UTC | Etc/Universal) tz_default=UTC ;; esac
  # About 1 GB each, after 2 GB for voice; the app's own default is 4.
  suggested=$((ram_gb - 2))
  [ "$suggested" -ge 1 ] || suggested=1
  [ "$suggested" -le 4 ] || suggested=4
  if $tui; then
    ask_settings_tui "$tz_default" "$suggested"
    return
  fi

  tz="$(ask "Time zone for the bots' clocks and routines, like America/New_York" "$tz_default" "${DISPATCH_TZ:-}")"
  while ! valid_tz "$tz"; do
    { $interactive && [ -z "${DISPATCH_TZ:-}" ]; } || die "$tz is not a time zone. Use a name like Europe/London or America/New_York."
    warn "$tz is not a time zone. Use a name like Europe/London or America/New_York."
    tz="$(ask "Time zone" "$tz_default")"
  done

  max_bots="$(ask "How many bots at most (about 1 GB of memory each)" "$suggested" "${DISPATCH_MAX_BOTS:-}")"
  while ! [[ "$max_bots" =~ ^[1-9][0-9]?$ ]]; do
    { $interactive && [ -z "${DISPATCH_MAX_BOTS:-}" ]; } || die "The number of bots has to be a number from 1 to 99."
    warn "Type a number from 1 to 99."
    max_bots="$(ask "How many bots at most" "$suggested")"
  done

  if [ -n "${DISPATCH_TAILSCALE:-}" ]; then
    tailscale_too="$DISPATCH_TAILSCALE"
    info "Set up Tailscale too: $([ "$tailscale_too" = 1 ] && echo yes || echo no)"
  elif $interactive; then
    info "Dispatch uses HTTPS with a certificate of its own, which browsers warn about once per device."
    info "Tailscale adds an address that has no warning and works from anywhere (free account)."
    if confirm "Set up Tailscale too?"; then tailscale_too=1; else tailscale_too=0; fi
  else
    tailscale_too=0
  fi
}

# At full screen: a screen per question, skipping those the environment answers, then the review.
ask_settings_tui() {
  tz=${DISPATCH_TZ:-$1} max_bots=${DISPATCH_MAX_BOTS:-$2} tailscale_too=${DISPATCH_TAILSCALE:-0}
  valid_tz "$tz" || die "$tz is not a time zone. Use a name like Europe/London or America/New_York."
  [[ "$max_bots" =~ ^[1-9][0-9]?$ ]] || die "The number of bots has to be a number from 1 to 99."
  while :; do
    [ -n "${DISPATCH_TZ:-}" ] || pick_tz
    [ -n "${DISPATCH_MAX_BOTS:-}" ] || pick_bots
    [ -n "${DISPATCH_TAILSCALE:-}" ] || pick_tailscale
    review && break
    # Change: every question again, the environment's answers too.
    DISPATCH_TZ='' DISPATCH_MAX_BOTS='' DISPATCH_TAILSCALE=''
  done
}

write_settings() {
  install -d -m 0700 /etc/dispatch
  (
    umask 077
    cat >/etc/dispatch/env.new <<EOF
# Dispatch's settings, read by its systemd service. After changing one: systemctl restart dispatch
# .env.example in Dispatch's source lists the others.
MAX_BOTS=$max_bots
TZ=$tz
# Every address, so Dispatch is on the local network. 127.0.0.1 keeps it to this machine (and to
# Tailscale Serve, if that is set up).
HOST=0.0.0.0
# HTTPS with Dispatch's own certificate, on the same port, for voice calls: browsers allow the
# microphone only over HTTPS.
HTTPS=1
EOF
  )
  mv /etc/dispatch/env.new /etc/dispatch/env
}

# Where this install comes from, which the app checks for updates (server/src/updates.ts): the
# repository, and the branch it follows if it follows one. Written on every run, so updates follow
# what was installed last. The version a machine runs is the running release's VERSION file
# (fetch_release), so a release that fails and is rolled back never counts as installed.
write_source() {
  install -d -m 0700 /etc/dispatch
  {
    echo '# Where scripts/install.sh installed Dispatch from. The app checks it for updates: the newest'
    echo '# signed release, or with DISPATCH_REF the newest commit of that branch.'
    printf 'DISPATCH_REPO=%s\nDISPATCH_REF=%s\n' "$repo" "$ref"
  } >/etc/dispatch/source.new
  mv /etc/dispatch/source.new /etc/dispatch/source
}

# The release this machine runs, from its VERSION file, or nothing (none yet, or a branch's commit).
installed_version() {
  sed -nE '1s/^(v[0-9]+\.[0-9]+\.[0-9]+)$/\1/p' /srv/dispatch/current/VERSION 2>/dev/null || true
}

# ---------------------------------------------------------------- Tailscale

tailscale_up() { tailscale status --json 2>/dev/null | grep -q '"BackendState": *"Running"'; }

# Tailscale from its apt repository, which keeps one per Ubuntu and Debian release (a derivative uses
# its base's). Its signing key is trusted only with the fingerprint below. Tailscale doesn't publish
# it; it is the key Tailscale's own installer downloads, on keyserver.ubuntu.com since 2020 as
# "Tailscale Inc. (Package repository signing key)". Output goes to the log.
install_tailscale() {
  local os codename tmp got key=/usr/share/keyrings/tailscale-archive-keyring.gpg want=2596A99EAAB33821893C0A79458CA832957F5868
  # shellcheck disable=SC1091
  os="$(. /etc/os-release && case " $ID ${ID_LIKE:-} " in *" ubuntu "*) echo ubuntu ;; *) echo debian ;; esac)"
  # shellcheck disable=SC1091
  codename="$(. /etc/os-release && echo "${UBUNTU_CODENAME:-${VERSION_CODENAME:-}}")"
  [ -n "$codename" ] || { echo "No release codename in /etc/os-release"; return 1; }
  command -v gpg >/dev/null || { apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends gnupg; } || return 1
  tmp="$(mktemp)"
  curl -fsSL "https://pkgs.tailscale.com/stable/$os/$codename.noarmor.gpg" -o "$tmp" || { rm -f "$tmp"; return 1; }
  got="$(gpg --show-keys --with-colons "$tmp" 2>/dev/null | awk -F: '$1 == "pub" { p = 1 } $1 == "fpr" && p { print $10; p = 0 }')"
  if [ "$got" != "$want" ]; then
    echo "Tailscale's signing key isn't the one expected ($want), so it isn't trusted. It has: $got"
    rm -f "$tmp"
    return 1
  fi
  install -m 0644 "$tmp" "$key"
  rm -f "$tmp"
  printf 'Types: deb\nURIs: https://pkgs.tailscale.com/stable/%s\nSuites: %s\nComponents: main\nSigned-By: %s\n' "$os" "$codename" "$key" >/etc/apt/sources.list.d/tailscale.sources
  apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq tailscale && systemctl enable --now tailscaled
}

# At full screen its output goes to the log, and the screen shows the link Tailscale waits on.
setup_tailscale() {
  if ! command -v tailscale >/dev/null; then
    info "Installing Tailscale"
    install_tailscale >>"$LOG" 2>&1 || die "Tailscale didn't install. The log is $LOG."
  fi
  if ! tailscale_up; then
    info "Sign this machine in to your tailnet with the link below."
    tailscale up 2>&1 | sed -u 's/^/   /' || die "Tailscale didn't sign in."
  fi
  # HTTPS on the machine's tailnet name. Serve needs HTTPS turned on for the tailnet; when it isn't,
  # tailscale prints a link to turn it on and waits.
  if [ -z "$(tailscale_url)" ]; then
    tailscale serve --bg --https=443 "http://127.0.0.1:$PORT" 2>&1 | sed -u 's/^/   /' || die "Tailscale Serve didn't start."
  fi
  info "$G$OK$R Dispatch will also be at $(tailscale_url)"
}

# ---------------------------------------------------------------- the release

# The keys that sign Dispatch's releases, in ssh-keygen's allowed signers format. The installer installs
# a release only when one of them signed both its tag (as git) and the checksums of what GitHub
# Actions built from it (as dispatch-release, so neither signature can stand in for the other). An
# update runs the installer of the release it updates from, so a release can change this list only if
# a key already on it signed that release. scripts/publish.sh signs with one of them.
release_signers() {
  cat <<'EOF'
dispatch namespaces="git,dispatch-release" ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIBMSc9gHrkDHjyiDVKCPOIm1aJlbAGswe01RpgEsWdFV
EOF
}

# git for GitHub: GITHUB_TOKEN reads a private fork, from the environment rather than the command
# line, where other users could see it, and git never stops to ask for a password.
github_git() {
  if [ -n "${GITHUB_TOKEN:-}" ]; then
    GIT_TERMINAL_PROMPT=0 GIT_CONFIG_COUNT=1 GIT_CONFIG_KEY_0=http.https://github.com/.extraHeader \
      GIT_CONFIG_VALUE_0="Authorization: Basic $(printf 'x-access-token:%s' "$GITHUB_TOKEN" | base64 -w0)" git "$@"
  else
    GIT_TERMINAL_PROMPT=0 git "$@"
  fi
}

# git fetches a release and ssh-keygen checks its signature. Most servers have both.
release_tools() {
  local missing=()
  command -v git >/dev/null || missing+=(git)
  command -v ssh-keygen >/dev/null || missing+=(openssh-client)
  [ ${#missing[@]} -gt 0 ] || return 0
  info "Installing ${missing[*]}"
  { apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends "${missing[@]}"; } >>"$LOG" 2>&1 ||
    die "${missing[*]} didn't install. The log is $LOG."
}

# newest_release <repository url>: the highest vX.Y.Z tag there, or nothing when it has none. Other
# tags, such as v2.0.0-rc1, aren't releases.
newest_release() {
  local refs
  refs="$(github_git ls-remote --tags --refs "$1")" || return 1
  sed -nE 's#^[0-9a-f]{40}\trefs/tags/(v[0-9]+\.[0-9]+\.[0-9]+)$#\1#p' <<<"$refs" | sort -V | tail -n 1
}

# older <a> <b>: whether version a comes before version b.
older() { [ "$1" != "$2" ] && [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V | head -n 1)" = "$1" ]; }

# fetch_signed <repository url> <tag> <folder>: fetches the tag and its commit into a repository in the
# folder, and sets sha to the commit once one of release_signers' keys is found to have signed the
# tag. git checks every object it fetches against its hash, so the files are the ones the signature
# covers. The signature is checked as git verify-tag checks one, with ssh-keygen (OpenSSH 8.2 and
# later), over the tag's text before the signature. That text names the commit and the tag itself, so
# the signed tag of one release can't be passed off as another.
fetch_signed() {
  local url=$1 tag=$2 dir=$3 git=$3/repo.git
  git init -q --bare "$git" || die "Couldn't make a folder to download $tag into."
  github_git -C "$git" fetch -q --depth 1 --no-tags "$url" "refs/tags/$tag:refs/tags/$tag" ||
    die "The download of $tag from $url failed."
  [ "$(git -C "$git" cat-file -t "refs/tags/$tag")" = tag ] ||
    die "$tag in $url isn't signed (it's a plain tag), so the installer won't install it."
  git -C "$git" cat-file tag "refs/tags/$tag" >"$dir/tag"
  sed '/^-----BEGIN SSH SIGNATURE-----$/,$d' "$dir/tag" >"$dir/signed"
  sed -n '/^-----BEGIN SSH SIGNATURE-----$/,$p' "$dir/tag" >"$dir/signature"
  release_signers >"$dir/signers"
  if [ ! -s "$dir/signature" ] ||
    ! ssh-keygen -Y verify -f "$dir/signers" -I dispatch -n git -s "$dir/signature" <"$dir/signed" >/dev/null 2>&1; then
    die "$tag in $url isn't signed with a Dispatch release key, so the installer won't install it."
  fi
  # The header of what was signed: object <commit>, type commit, tag <name>, then the tagger.
  local object type name
  object="$(awk '$0 == "" { exit } $1 == "object" { print $2 }' "$dir/signed")"
  type="$(awk '$0 == "" { exit } $1 == "type" { print $2 }' "$dir/signed")"
  name="$(awk '$0 == "" { exit } $1 == "tag" { print $2 }' "$dir/signed")"
  [ "$name" = "$tag" ] || die "The tag $tag in $url is the signed tag of ${name:-another release}, so the installer won't install it."
  [ "$type" = commit ] && [[ "$object" =~ ^[0-9a-f]{40}$ ]] || die "$tag in $url doesn't name a commit."
  sha=$object
}

# fetch_assets <url> <tag> <commit> <folder>: downloads what GitHub Actions built for the release from
# <url> (its GitHub release): the tarball, its manifest.json and SHA256SUMS, which lists both. They
# are accepted only when one of release_signers' keys signed SHA256SUMS (SHA256SUMS.sig, as
# dispatch-release), both files match it, and the manifest names this tag and the commit that the
# signed tag names (fetch_signed). Leaves the tarball as <folder>/dispatch.tar.gz.
fetch_assets() {
  local url=$1 tag=$2 commit=$3 dir=$4 name="dispatch-$2-linux-amd64.tar.gz" f version built
  for f in SHA256SUMS SHA256SUMS.sig manifest.json "$name"; do
    curl -fsSL "$url/$f" -o "$dir/$f" || die "The download of $f for $tag from $url failed."
  done
  release_signers >"$dir/signers"
  ssh-keygen -Y verify -f "$dir/signers" -I dispatch -n dispatch-release -s "$dir/SHA256SUMS.sig" <"$dir/SHA256SUMS" >/dev/null 2>&1 ||
    die "The checksums of $tag aren't signed with a Dispatch release key, so the installer won't install it."
  # Both lines must be there: sha256sum would pass a list without them with --ignore-missing.
  awk -v n="$name" '$2 == n || $2 == "manifest.json"' "$dir/SHA256SUMS" >"$dir/wanted"
  [ "$(wc -l <"$dir/wanted")" -eq 2 ] || die "The checksums of $tag don't list its tarball and manifest."
  (cd "$dir" && sha256sum -c --quiet --strict wanted >/dev/null 2>&1) ||
    die "The download of $tag doesn't match its signed checksums, so the installer won't install it."
  # The manifest is written one key a line (.github/workflows/release.yml), and its checksum is signed.
  version="$(sed -nE 's/^ *"version": *"([^"]*)",?$/\1/p' "$dir/manifest.json")"
  built="$(sed -nE 's/^ *"commit": *"([0-9a-f]{40})",?$/\1/p' "$dir/manifest.json")"
  [ "$version" = "$tag" ] && [ "$built" = "$commit" ] ||
    die "The build attached to $tag is of ${version:-another release} at ${built:-another commit}, not of $tag at $commit, so the installer won't install it."
  mv "$dir/$name" "$dir/dispatch.tar.gz"
}

# Sets commit and script (the release.sh to run), or up_to_date when that commit already runs. With no
# DISPATCH_REF, the newest release (and tag, its version), checked as fetch_signed says, even when
# its commit runs already, so an unsigned tag can't be written down as the version this machine runs;
# what is unpacked is its built tarball, checked as fetch_assets says. DISPATCH_RELEASES_URL sets
# where the releases' files are (scripts/test_install.py). With DISPATCH_REF, the source of the newest
# commit of that branch, tag or commit, which only GitHub vouches for, and which release.sh builds.
fetch_release() {
  local api="https://api.github.com/repos/$repo" url="https://github.com/$repo.git" auth=() sha what had
  local releases=/srv/dispatch/releases
  [ -z "${GITHUB_TOKEN:-}" ] || auth=(-H "Authorization: Bearer $GITHUB_TOKEN")
  if [ -z "$ref" ]; then
    release_tools
    tag="$(newest_release "$url")" || die "Couldn't reach $url."
    [ -n "$tag" ] || die "$url has no release yet."
    had="$(installed_version)"
    if [ -n "$had" ] && older "$tag" "$had"; then
      die "The newest release in $url is $tag, older than $had, which this machine runs. The installer doesn't go back a version."
    fi
    fetch_dir="$(mktemp -d)"
    fetch_signed "$url" "$tag" "$fetch_dir"
    what="$tag (signed)"
  else
    sha="$(curl -fsSL "${auth[@]}" -H 'Accept: application/vnd.github.sha' "$api/commits/$ref")" ||
      die "Couldn't find $ref in github.com/$repo."
    [[ "$sha" =~ ^[0-9a-f]{40}$ ]] || die "GitHub didn't name a commit for $ref."
    what=$ref
  fi
  # Twelve characters, as scripts/deploy.sh names releases, so both reuse the same ones.
  commit="${sha:0:12}"
  up_to_date=false
  if [ "$(readlink /srv/dispatch/current 2>/dev/null)" = "releases/$commit" ] && systemctl is-active --quiet dispatch; then
    up_to_date=true
    info "$what is $commit, which is running already"
  elif [ -d "$releases/$commit" ]; then
    info "$what is $commit, built before"
    script="$releases/$commit/scripts/release.sh"
  else
    rm -rf "$releases/$commit.new"
    mkdir -p "$releases/$commit.new"
    if [ -n "$fetch_dir" ]; then
      fetch_assets "${DISPATCH_RELEASES_URL:-https://github.com/$repo/releases/download}/$tag" "$tag" "$sha" "$fetch_dir"
      tar -xzf "$fetch_dir/dispatch.tar.gz" -C "$releases/$commit.new" && [ -x "$releases/$commit.new/node/bin/node" ] ||
        die "Unpacking $tag failed."
    else
      curl -fsSL "${auth[@]}" "$api/tarball/$sha" | tar -xz -C "$releases/$commit.new" --strip-components=1 ||
        die "The download of $commit failed."
    fi
    info "$what is $commit"
    script="$releases/$commit.new/scripts/release.sh"
  fi
  # A signed release says which version it is, for the app and installed_version. Only a checked tag
  # is written down; a branch's commit has no version.
  if [ -n "$tag" ]; then
    local dir="$releases/$commit"
    [ -d "$dir" ] || dir="$releases/$commit.new"
    echo "$tag" >"$dir/VERSION"
  fi
  [ -z "$fetch_dir" ] || { rm -rf "$fetch_dir"; fetch_dir=''; }
}

# progress <offset>: release.sh's steps as they reach the log after <offset>, line by line (the full
# screen has tui_progress). At a terminal the current one has a spinner and its time, and TERM marks
# it done, USR1 failed; otherwise each step is a line as it starts. Until release.sh names its first
# step, the spinner says Starting.
progress() {
  local offset=$1 shown=0 tick=0 since=$SECONDS current='Starting' started=false line lines=()
  ended() {
    if $fancy; then printf '\r\e[K   %s %s %s%s%s\n' "$1" "$current" "$D" "$(clock $((SECONDS - since)))" "$R"; fi
  }
  trap 'ended "$G$OK$R"; exit 0' TERM
  trap 'ended "$E$NO$R"; exit 0' USR1
  while :; do
    if [ $((tick % 4)) -eq 0 ]; then
      mapfile -t lines < <(tail -c "+$((offset + 1))" "$LOG" | sed -nE 's/^\[(provision|release)\] //p')
      while [ "$shown" -lt "${#lines[@]}" ]; do
        line="$(describe "${lines[shown]}")"
        line=${line#*|}
        shown=$((shown + 1))
        [ -n "$line" ] || continue
        if $started; then ended "$G$OK$R"; fi
        current="$line" since=$SECONDS started=true
        if ! $fancy; then info "$current"; fi
      done
    fi
    if $fancy; then
      # Cut to the terminal's width: a line that wraps can't be redrawn in place.
      tui_size || cols=80
      printf '\r\e[K   %s %s %s%s%s' "${SPIN[tick % ${#SPIN[@]}]}" "${current:0:cols-12}" "$D" "$(clock $((SECONDS - since)))" "$R"
    fi
    tick=$((tick + 1))
    sleep 0.25
  done
}

# What this script's steps (mark), release.sh and provision.sh say, as key|words for someone
# installing; empty skips the line. The key places a step among those the full screen expects
# (work_begin), whose words come from here too.
describe() {
  case "$1" in
    tailscale) echo 'tailscale|Setting up Tailscale' ;;
    download) echo 'download|Downloading Dispatch' ;;
    'provisioning the host' | provision) echo 'provision|Setting up the machine' ;;
    packages) echo 'packages|Installing Chrome, Node, Docker and the desktop packages' ;;
    'Hermes Agent '*) echo "hermes|Installing $1" ;;
    hermes) echo 'hermes|Installing Hermes Agent' ;;
    done | 'Dispatch runs '*) ;;
    'pulling the speech service') echo 'speech|Downloading the speech service' ;;
    'building dispatch-speech'*) echo 'speech|Building the speech service (about ten minutes)' ;;
    # A release's speech image is downloaded; a branch's is built.
    speech) if [ -z "$ref" ]; then echo 'speech|Downloading the speech service'; else echo 'speech|Building the speech service (about ten minutes)'; fi ;;
    'building '* | build) echo 'build|Building Dispatch' ;;
    'starting '* | start) echo 'start|Starting Dispatch' ;;
    *) echo "other|$1" ;;
  esac
}

# release.sh's output goes to the log, and the full screen or progress shows its steps.
run_release() {
  if ! $tui; then
    if $installed; then step "Updating"; else step "Installing"; fi
    $installed || note "The first install takes 15 to 30 minutes, and can be left to finish."
    note "The full log is $LOG"
    local offset
    offset="$(stat -c %s "$LOG")"
    progress "$offset" &
    watcher=$!
  fi
  if bash "$script" >>"$LOG" 2>&1 </dev/null; then
    $tui || stop_watcher TERM
  else
    stop_watcher USR1
    tui_end
    printf '\n%sThe last lines of %s:%s\n' "$D" "$LOG" "$R" >&2
    tail -n 30 "$LOG" | sed 's/^/   /' >&2
    die "Dispatch didn't install. Fix what the log says and run the installer again; it picks up where it stopped."
  fi
}

# ---------------------------------------------------------------- done

# The address this machine reaches the network from: its LAN address, or a server's public one.
lan_address() {
  local ip
  ip="$(ip -4 route get 1.1.1.1 2>/dev/null | grep -o 'src [0-9.]*' | cut -d' ' -f2)"
  [ -n "$ip" ] || ip="$(hostname -I 2>/dev/null | awk '{ print $1 }')"
  echo "${ip:-$(hostname)}"
}

private_address() {
  case "$1" in
    10.* | 192.168.* | 172.1[6-9].* | 172.2[0-9].* | 172.3[01].* | 100.6[4-9].* | 100.[7-9][0-9].* | 100.1[01][0-9].* | 100.12[0-7].*) return 0 ;;
    *) return 1 ;;
  esac
}

# The HTTPS address Tailscale Serve gives Dispatch, once someone has set that up.
tailscale_url() {
  local status
  command -v tailscale >/dev/null || return 0
  status="$(tailscale serve status 2>/dev/null)" || return 0
  case "$status" in *"127.0.0.1:$PORT"*) grep -o 'https://[^ ]*' <<<"$status" | head -1 ;; esac
}

finish() {
  local url address listening lan=false scheme=http code='' setup=''
  if $up_to_date; then
    printf '\n%s%s Dispatch is up to date%s %s(%s)%s\n\n' "$G$B" "$OK" "$R" "$D" "$commit" "$R"
  else
    printf '\n%s%s Dispatch is running%s %s(%s)%s\n\n' "$G$B" "$OK" "$R" "$D" "$commit" "$R"
  fi
  # An install can keep the server to 127.0.0.1 (HOST in /etc/dispatch/env), or to plain HTTP (HTTPS).
  listening="$(ss -Hltn "sport = :$PORT" | awk '{ print $4 }')"
  case "$listening" in '' | 127.0.0.1:*) ;; *) lan=true ;; esac
  curl -fsk --max-time 5 -o /dev/null "https://127.0.0.1:$PORT/api/health" && scheme=https
  url="$(tailscale_url || true)"
  url="${url%/}"
  address="$(lan_address)"
  # Until the account exists, making it takes the setup code (server/src/lib/auth.ts), which the
  # address carries for the web app to fill in.
  if curl -fsS --max-time 5 "http://127.0.0.1:$PORT/api/auth/me" 2>/dev/null | grep -q '"needsAccount":true'; then
    code="$(cat /var/lib/dispatch/setup-code 2>/dev/null || true)"
    setup="${code:+/#setup=$code}"
  fi
  if $lan; then
    info "Open $B$scheme://$address:$PORT$setup$R"
    [ -z "$url" ] || info "or $B$url$setup$R from anywhere on your tailnet"
    if [ "$scheme" = https ]; then
      info "The browser warns that the connection isn't private, because Dispatch signs its own certificate."
      info "Continue past it once per device, or install the certificate from Settings > General."
    fi
  elif [ -n "$url" ]; then
    info "Open $B$url$setup$R"
  else
    info "Dispatch listens on this machine only (HOST in /etc/dispatch/env). Reach it with"
    info "  $B""ssh -N -L $PORT:127.0.0.1:$PORT ${SUDO_USER:-root}@$address$R"
    info "then open $B""http://127.0.0.1:$PORT$setup$R"
  fi
  if [ -n "$code" ]; then
    info "Make your account there. The link carries its one-time setup code, $B$code$R; without it nobody can."
  fi
  if $lan && ! private_address "$address"; then
    warn "$address is a public address, so Dispatch is open to the internet. Block port $PORT in a firewall and reach Dispatch through Tailscale instead."
  elif $lan && command -v ufw >/dev/null && ufw status 2>/dev/null | grep -q '^Status: active'; then
    warn "The firewall (ufw) is on. Let the local network reach Dispatch with: ufw allow $PORT/tcp"
  fi
  echo
  if [ -z "$url" ] && [ "$scheme" = http ]; then
    note "Voice calls need HTTPS, since browsers allow the microphone only there. Set HTTPS=1 in"
    note "/etc/dispatch/env, or put Tailscale on this machine and run:"
    note "  tailscale serve --bg --https=443 http://127.0.0.1:$PORT"
    echo
  fi
  note "Logs: journalctl -u dispatch -f"
  note "Settings: /etc/dispatch/env, then systemctl restart dispatch"
  note "Update: Settings > General in Dispatch, or run the installer again"
}

# ---------------------------------------------------------------- main

main() {
  set -euo pipefail
  PORT=8787
  ui_init
  steps=0 tui=false tty3=false watcher='' reported=false machine='' gum_dir='' fetch_dir='' LOG=''
  [ "$(id -u)" -eq 0 ] || become_root DISPATCH_YES DISPATCH_TZ DISPATCH_MAX_BOTS DISPATCH_TAILSCALE DISPATCH_REF DISPATCH_REPO GITHUB_TOKEN

  repo="${DISPATCH_REPO:-chriscorbell/dispatch}" ref="${DISPATCH_REF:-}" tag=''
  interactive=false
  if [ -z "${DISPATCH_YES:-}" ] && (exec </dev/tty) 2>/dev/null; then interactive=true; fi
  installed=false
  [ -e /srv/dispatch/current ] && installed=true

  # One install at a time.
  exec 9>/run/dispatch-install.lock
  flock -n 9 || die "The installer is running already."
  install -d -m 0755 /var/log/dispatch
  LOG=/var/log/dispatch/install.log
  : >"$LOG"
  trap on_exit EXIT
  # Ctrl+C and hang-ups end it through on_exit too, with their status: untrapped, on_exit would see 0.
  trap 'exit 130' INT
  trap 'exit 129' HUP
  trap 'exit 143' TERM

  local host
  host="$(hostname)"
  if $installed; then
    doing="Updating on $host" stages=(Machine Update Done)
    printf '%sUpdating Dispatch%s on %s\n' "$B" "$R" "$host"
  else
    doing="Installing on $host" stages=(Machine Settings Install Done)
    printf '%sInstalling Dispatch%s on %s\n' "$B" "$R" "$host"
  fi
  tui_start

  stage=0
  $tui || step "Checking this machine"
  check_machine

  if ! $installed; then
    stage=1
    $tui || step "Settings"
    ask_settings
  fi

  work_begin
  if [ "${tailscale_too:-0}" = 1 ]; then
    mark tailscale "Tailscale"
    quietly setup_tailscale
  fi
  mark download "Downloading Dispatch"
  quietly fetch_release
  write_source
  if $up_to_date; then
    work_end
    finish
    return
  fi
  if ! $installed || [ ! -s /etc/dispatch/env ]; then
    : "${tz:=UTC}" "${max_bots:=4}"
    write_settings
  fi
  run_release
  work_end
  finish
}

main
